"""Anmeldung im LAN: Rollen, eindeutige Spielernamen, zwei Plätze, Wiederkehr und Rechte am Server."""

import pytest
from starlette.testclient import TestClient

from hebocon.app import App
from hebocon.config import Settings
from hebocon.lobby import Lobby, LobbyError
from hebocon.server import create_server

from .test_app import FakeCamera


def test_roles_follow_the_name(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "geheim")
    assert lobby.join("Stage")["role"] == "stage"
    with pytest.raises(LobbyError) as err:
        lobby.join("mod", "admin")
    assert err.value.code == "password"
    assert lobby.join("Moderator", "geheim")["role"] == "moderator"
    assert lobby.join("Kiste") == {"token": lobby.players["kiste"]["token"], "role": "player",
                                   "name": "Kiste", "slot": 1}


def test_two_unique_players_then_full(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    a = lobby.join("Kiste")
    with pytest.raises(LobbyError) as err:
        lobby.join("KISTE")
    assert err.value.code == "taken"
    assert lobby.join("Dose")["slot"] == 2
    with pytest.raises(LobbyError) as err:
        lobby.join("Drei")
    assert err.value.code == "full"
    # Gleiches Gerät, gleicher Name: derselbe Platz, kein zweiter Spieler; die Schreibweise darf wechseln.
    again = lobby.join("kiste", token=a["token"])
    assert (again["token"], again["slot"], again["name"]) == (a["token"], 1, "kiste")
    assert len(lobby.public()["players"]) == 2


def test_leave_and_kick_free_the_slot_but_keep_the_name(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    a = lobby.join("Kiste")
    lobby.join("Dose")
    assert lobby.leave(a["token"]) == 1
    assert lobby.session(a["token"])["slot"] is None
    assert lobby.join("Drei")["slot"] == 1
    assert lobby.kick(2) == "Dose"
    assert [p["name"] for p in lobby.public()["players"]] == ["Drei"]
    assert "kiste" in lobby.players
    # Mit dem alten Token kommt Kiste auf den freien Platz zurück.
    assert lobby.join("Kiste", token=a["token"])["slot"] == 2


def test_rename_keeps_the_slot(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    a = lobby.join("Kiste")
    lobby.join("Dose")
    b = lobby.join("Box", token=a["token"])
    assert (b["slot"], b["token"]) == (1, a["token"])
    assert {p["name"] for p in lobby.public()["players"]} == {"Box", "Dose"}


def test_reserved_and_too_long_names(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    with pytest.raises(LobbyError):
        lobby.join("   ")
    with pytest.raises(LobbyError):
        lobby.join("x" * 25)
    assert lobby.players == {}


def test_lobby_survives_restart(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    a = lobby.join("Kiste")
    m = lobby.join("mod", "admin")
    again = Lobby(tmp_path / "lobby.json", "admin")
    assert again.server_id == lobby.server_id
    assert again.session(a["token"]) == {"role": "player", "name": "Kiste", "slot": 1}
    assert again.session(m["token"])["role"] == "moderator"


@pytest.fixture
def client(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    app = App(Settings(segment_enabled=False, intro_s=0, _env_file=None), lobby=lobby)
    app.camera = FakeCamera()
    with TestClient(create_server(app, tmp_path / "media", lobby)) as c:
        c.app_state = app
        yield c


def login(client, name, password=""):
    r = client.post("/lobby/join", json={"name": name, "password": password})
    assert r.status_code == 200, r.text
    return {"Authorization": f"Bearer {r.json()['token']}"}


def test_only_the_moderator_may_act(client):
    assert client.post("/api/hud", json={"on": False}).status_code == 401
    assert client.post("/api/hud", json={"on": False}, headers=login(client, "stage")).status_code == 403
    player = login(client, "Kiste")
    assert client.post("/api/hud", json={"on": False}, headers=player).status_code == 403
    assert client.post("/media", content=b"x", headers=player).status_code == 403
    assert client.app_state.hud is True
    mod = login(client, "mod", "admin")
    assert client.post("/api/hud", json={"on": False}, headers=mod).status_code == 200
    assert client.app_state.hud is False
    # Medienende darf jede angemeldete Bühne melden.
    assert client.post("/api/cue", json={"kind": "ended", "id": 99}, headers=player).status_code == 200


def test_player_ulti_is_bound_to_own_slot(client):
    login(client, "Kiste")
    dose = login(client, "Dose")
    seen = []
    client.app_state.do_ulti = lambda player: seen.append(player)
    assert client.post("/api/ulti", json={"player": 1}, headers=dose).status_code == 200
    assert seen == [2]


def test_join_names_reach_state_and_kick(client):
    login(client, "Kiste")
    mod = login(client, "mod", "admin")
    app = client.app_state
    assert app.names[0] == "Kiste"
    assert app.state(0)["lobby"]["players"] == [{"slot": 1, "name": "Kiste", "online": False}]
    assert client.post("/api/kick", json={"slot": 1}, headers=mod).status_code == 200
    assert app.state(0)["lobby"]["players"] == []
    r = client.post("/lobby/join", json={"name": "moderator", "password": "falsch"})
    assert (r.status_code, r.json()["code"]) == (400, "password")


def test_websocket_needs_a_session(client):
    with client.websocket_connect("/ws?token=unbekannt") as ws:
        with pytest.raises(Exception):  # noqa: B017 – Starlette meldet das Schließen als eigene Ausnahme.
            ws.receive_bytes()
    token = login(client, "stage")["Authorization"][7:]
    # Ohne Kamerabild schickt der Server den Zustand allein; so braucht der Test keinen Kamera-Thread.
    client.app_state.camera.latest = lambda: None
    with client.websocket_connect(f"/ws?token={token}&frames=0") as ws:
        packet = ws.receive_bytes()
        length = int.from_bytes(packet[:4], "little")
        assert len(packet) == 4 + length
        assert client.app_state.lobby.public()["online"]["stage"] == 1
